insert into public.fanwen (code, sort_order, title, author, dynasty, source, genre, intro, sections, outline, theme, techniques, tips) values
  ('lunren', 1, '論仁、論孝、論君子', '孔子及其弟子', '春秋', '《論語》', '語錄體散文', '《論語》由孔子弟子及再傳弟子輯錄而成，記錄孔子及其弟子的言行。課文分別選錄孔子論「仁」、論「孝」、論「君子」的章節，集中反映儒家的道德修養觀。', '[{"heading":"論仁","paragraphs":["子曰：「不仁者不可以久處約，不可以長處樂。仁者安仁，知者利仁。」（〈里仁〉）","子曰：「富與貴，是人之所欲也；不以其道得之，不處也。貧與賤，是人之所惡也；不以其道得之，不去也。君子去仁，惡乎成名？君子無終食之間違仁，造次必於是，顛沛必於是。」（〈里仁〉）","顏淵問仁。子曰：「克己復禮為仁。一日克己復禮，天下歸仁焉。為仁由己，而由人乎哉？」顏淵曰：「請問其目。」子曰：「非禮勿視，非禮勿聽，非禮勿言，非禮勿動。」顏淵曰：「回雖不敏，請事斯語矣。」（〈顏淵〉）"]},{"heading":"論孝","paragraphs":["孟懿子問孝。子曰：「無違。」樊遲御，子告之曰：「孟孫問孝於我，我對曰：『無違。』」樊遲曰：「何謂也？」子曰：「生，事之以禮；死，葬之以禮，祭之以禮。」（〈為政〉）","子游問孝。子曰：「今之孝者，是謂能養。至於犬馬，皆能有養；不敬，何以別乎？」（〈為政〉）","子夏問孝。子曰：「色難。有事，弟子服其勞；有酒食，先生饌，曾是以為孝乎？」（〈為政〉）","子曰：「事父母幾諫，見志不從，又敬不違，勞而不怨。」（〈里仁〉）"]},{"heading":"論君子","paragraphs":["子曰：「君子不重則不威，學則不固。主忠信，無友不如己者，過則勿憚改。」（〈學而〉）","子曰：「君子成人之美，不成人之惡。小人反是。」（〈顏淵〉）","子曰：「君子義以為質，禮以行之，孫以出之，信以成之。君子哉！」（〈衛靈公〉）","子曰：「君子病無能焉，不病人之不己知也。」（〈衛靈公〉）","子曰：「君子求諸己，小人求諸人。」（〈衛靈公〉）","子曰：「君子恥其言而過其行。」（〈憲問〉）"]}]'::jsonb, '[{"label":"論仁（一）","summary":"不仁者不能長久處於窮困或安樂；仁者安於行仁，智者因明白仁有利而行仁。"},{"label":"論仁（二）","summary":"富貴貧賤都要以正當途徑取捨；君子連吃一頓飯的時間也不離開仁，倉卒、困頓時亦然。"},{"label":"論仁（三）","summary":"克制私慾、使言行合乎禮就是仁；行仁全靠自己，具體條目是視、聽、言、動都合乎禮。"},{"label":"論孝（一）","summary":"孝就是「無違」——父母在生時以禮侍奉，死後以禮安葬和祭祀。"},{"label":"論孝（二）","summary":"只供養父母而不敬重，與飼養犬馬無異；孝的核心在於「敬」。"},{"label":"論孝（三）","summary":"孝最難在於保持和悅的臉色；只代勞和奉上酒食，算不上孝。"},{"label":"論孝（四）","summary":"父母有過，子女應委婉勸諫；父母不聽，仍要恭敬不違逆，憂勞而不怨恨。"},{"label":"論君子（一）","summary":"君子要莊重才有威嚴，以忠信為主，結交勝過自己的朋友，有過勇於改正。"},{"label":"論君子（二）","summary":"君子成全別人的好事，不促成別人的壞事；小人相反。"},{"label":"論君子（三）","summary":"君子以義為本質，以禮實行，以謙遜的言辭表達，以誠信完成。"},{"label":"論君子（四）","summary":"君子只擔心自己沒有才能，不擔心別人不了解自己。"},{"label":"論君子（五）","summary":"君子凡事要求自己，小人凡事要求別人。"},{"label":"論君子（六）","summary":"君子以說得多、做得少為恥，要求言行一致。"}]'::jsonb, '三組章節從不同角度闡述儒家的道德理想：「仁」是最高的道德準則，關鍵在克己復禮、時刻不違；「孝」以「禮」和「敬」為本，不止於物質供養；「君子」是實踐仁德的理想人格，重視反求諸己、言行一致和成人之美。三者一脈相承，由內在修養推展到家庭和人際關係。', '[{"name":"語錄體、對話形式","detail":"以「子曰」或問答記錄孔子言論，語言簡潔；孔子往往因應發問者的情況作答（因材施教），例如孟懿子問孝答「無違」、子游問孝強調「敬」、子夏問孝則答「色難」。"},{"name":"對比","detail":"「君子求諸己，小人求諸人」「君子成人之美……小人反是」以君子與小人對比；「富與貴」與「貧與賤」對舉，突出君子取捨以「道」為準。"},{"name":"類比","detail":"以「至於犬馬，皆能有養」類比，指出只養不敬便與飼養牲畜無異，說理生動有力。"},{"name":"排比","detail":"「非禮勿視，非禮勿聽，非禮勿言，非禮勿動」與「義以為質，禮以行之，孫以出之，信以成之」句式整齊，條理分明。"},{"name":"反問","detail":"「君子去仁，惡乎成名？」「不敬，何以別乎？」「曾是以為孝乎？」以反問加強語氣，引人深思。"}]'::jsonb, '["比較四章論孝的重點：「無違」（禮）、「敬」、「色難」、「幾諫」。","君子與小人的對比是常考題目，要能舉出原文例子。","留意通假字：「知者」（知通「智」）、「孫以出之」（孫通「遜」）；「惡乎成名」的「惡」是疑問代詞，解作「何、哪裏」。"]'::jsonb),
  ('yuwo', 2, '魚我所欲也', '孟子', '戰國', '《孟子・告子上》', '議論文（語錄體）', '孟子名軻，戰國時代儒家代表人物，主張性善論。本文選自《孟子・告子上》，論述在生死關頭應「捨生而取義」，並批評為物質利益而喪失本心的人。', '[{"heading":null,"paragraphs":["孟子曰：「魚，我所欲也；熊掌，亦我所欲也。二者不可得兼，舍魚而取熊掌者也。生，亦我所欲也；義，亦我所欲也。二者不可得兼，舍生而取義者也。","「生亦我所欲，所欲有甚於生者，故不為苟得也；死亦我所惡，所惡有甚於死者，故患有所不辟也。如使人之所欲莫甚於生，則凡可以得生者，何不用也？使人之所惡莫甚於死者，則凡可以辟患者，何不為也？由是則生而有不用也，由是則可以辟患而有不為也。是故所欲有甚於生者，所惡有甚於死者。非獨賢者有是心也，人皆有之，賢者能勿喪耳。","「一簞食，一豆羹，得之則生，弗得則死。嘑爾而與之，行道之人弗受；蹴爾而與之，乞人不屑也。萬鍾則不辯禮義而受之，萬鍾於我何加焉？為宮室之美，妻妾之奉，所識窮乏者得我與？鄉為身死而不受，今為宮室之美為之；鄉為身死而不受，今為妻妾之奉為之；鄉為身死而不受，今為所識窮乏者得我而為之：是亦不可以已乎？此之謂失其本心。」"]}]'::jsonb, '[{"label":"第一段","summary":"以「舍魚而取熊掌」作喻，引出中心論點：生與義不能兼得時，應「舍生而取義」。"},{"label":"第二段","summary":"從正反兩面論證人有比生更想要的（義）、比死更厭惡的（不義）；這種本心人人皆有，賢者只是能夠不喪失它。"},{"label":"第三段","summary":"以路人、乞丐寧死不受無禮施捨，對比有人為「萬鍾」厚祿而不辨禮義，指出這是「失其本心」。"}]'::jsonb, '本文闡述「舍生取義」的道理：義比生命更重要，人人本有羞惡之心（本心），應加以保存，不要為物質利益而喪失。', '[{"name":"比喻論證","detail":"以魚與熊掌的取捨比喻生與義的取捨，化抽象為具體，引出中心論點。"},{"name":"正反論證","detail":"先正面說「所欲有甚於生者」，再以「如使人之所欲莫甚於生……何不用也」作反面假設，使論點更嚴密。"},{"name":"舉例論證","detail":"以「行道之人」「乞人」寧死不受無禮施捨為例，證明人皆有羞惡之心。"},{"name":"對比","detail":"「鄉為身死而不受」與「今為宮室之美為之」對比，突出失其本心者的可鄙。"},{"name":"排比、反問","detail":"三個「鄉為身死而不受，今為……為之」構成排比，配合「是亦不可以已乎？」的反問，氣勢磅礴，加強批判力量。"}]'::jsonb, '["掌握論證結構：設喻引論 → 正反論證 → 舉例及對比 → 總結「失其本心」。","通假字：辟（避）、鄉（嚮，從前）、得（德，感激）、辯（辨）、與（歟）。","可與〈論仁〉「富與貴……不以其道得之，不處也」比較儒家的義利觀。"]'::jsonb),
  ('xiaoyao', 3, '逍遙遊（節錄）', '莊子', '戰國', '《莊子・內篇・逍遙遊》', '寓言式說理散文', '莊子名周，戰國時代道家代表人物，主張順應自然、追求精神自由。節錄部分記述莊子與好友惠施的兩段對話，透過「大瓠」和「大樹」兩個寓言，闡明「無用之用」的道理。', '[{"heading":null,"paragraphs":["惠子謂莊子曰：「魏王貽我大瓠之種，我樹之成而實五石。以盛水漿，其堅不能自舉也。剖之以為瓢，則瓠落無所容。非不呺然大也，吾為其無用而掊之。」莊子曰：「夫子固拙於用大矣。宋人有善為不龜手之藥者，世世以洴澼絖為事。客聞之，請買其方百金。聚族而謀曰：『我世世為洴澼絖，不過數金；今一朝而鬻技百金，請與之。』客得之，以說吳王。越有難，吳王使之將。冬，與越人水戰，大敗越人，裂地而封之。能不龜手，一也；或以封，或不免於洴澼絖，則所用之異也。今子有五石之瓠，何不慮以為大樽而浮乎江湖？而憂其瓠落無所容，則夫子猶有蓬之心也夫！」","惠子謂莊子曰：「吾有大樹，人謂之樗。其大本擁腫而不中繩墨，其小枝卷曲而不中規矩，立之塗，匠者不顧。今子之言，大而無用，眾所同去也。」莊子曰：「子獨不見狸狌乎？卑身而伏，以候敖者；東西跳梁，不辟高下；中於機辟，死於罔罟。今夫斄牛，其大若垂天之雲，此能為大矣，而不能執鼠。今子有大樹，患其無用，何不樹之於無何有之鄉，廣莫之野，彷徨乎無為其側，逍遙乎寢臥其下？不夭斤斧，物無害者，無所可用，安所困苦哉！」"]}]'::jsonb, '[{"label":"第一段","summary":"惠子以大瓠「無用」而打破它；莊子以「不龜手之藥」的寓言，說明同一事物用法不同，價值便有天淵之別，批評惠子「拙於用大」、「有蓬之心」。"},{"label":"第二段","summary":"惠子以樗樹不合繩墨規矩，諷刺莊子言論「大而無用」；莊子以狸狌因有用而喪命、斄牛雖大而不能捕鼠作對比，指出大樹正因無用才得以保全，可讓人逍遙自在。"}]'::jsonb, '透過兩段寓言式對話，闡明「無用之用」：事物的價值在於如何運用，不應以世俗的功利眼光衡量；看似無用，反能免於禍害，使人達致逍遙自在的精神境界。', '[{"name":"寓言說理","detail":"以大瓠、不龜手之藥、樗樹等寓言故事說理，化抽象為具體，生動有趣。"},{"name":"對話體","detail":"通過惠子與莊子的兩輪問答推進論述，惠子代表功利觀點，莊子逐一反駁，層層深入。"},{"name":"對比","detail":"同一「不龜手之藥」，宋人只用來漂洗絲絮，客卻用來「裂地而封」；狸狌靈巧卻「死於罔罟」，大樹無用卻「不夭斤斧」，對比鮮明。"},{"name":"比喻","detail":"以「蓬之心」比喻惠子心思閉塞、見識淺窄；以「垂天之雲」形容斄牛之大。"},{"name":"誇張","detail":"大瓠「實五石」、斄牛「其大若垂天之雲」，誇張想像，具浪漫色彩。"}]'::jsonb, '["理解兩段的結構相同：惠子提出「無用」→ 莊子以寓言反駁 → 提出「大用」或「無用之用」。","常考字詞：樹（種植）、實（容納）、瓠落（空廓）、掊（擊破）、說（游說）、塗（道路）。","通假字：辟（避）、塗（途）、敖（遨）。"]'::jsonb),
  ('quanxue', 4, '勸學（節錄）', '荀子', '戰國', '《荀子・勸學》', '議論文', '荀子名況，戰國末年儒家學者，主張性惡論，重視後天學習和禮的教化。〈勸學〉是《荀子》首篇，節錄部分論述學習的重要性、作用和應有的態度。', '[{"heading":null,"paragraphs":["君子曰：學不可以已。青，取之於藍，而青於藍；冰，水為之，而寒於水。木直中繩，輮以為輪，其曲中規，雖有槁暴，不復挺者，輮使之然也。故木受繩則直，金就礪則利，君子博學而日參省乎己，則知明而行無過矣。","吾嘗終日而思矣，不如須臾之所學也；吾嘗跂而望矣，不如登高之博見也。登高而招，臂非加長也，而見者遠；順風而呼，聲非加疾也，而聞者彰。假輿馬者，非利足也，而致千里；假舟楫者，非能水也，而絕江河。君子生非異也，善假於物也。","積土成山，風雨興焉；積水成淵，蛟龍生焉；積善成德，而神明自得，聖心備焉。故不積跬步，無以至千里；不積小流，無以成江海。騏驥一躍，不能十步；駑馬十駕，功在不舍。鍥而舍之，朽木不折；鍥而不舍，金石可鏤。螾無爪牙之利，筋骨之強，上食埃土，下飲黃泉，用心一也。蟹六跪而二螯，非蛇鱔之穴無可寄託者，用心躁也。"]}]'::jsonb, '[{"label":"第一段","summary":"提出中心論點「學不可以已」；以青出於藍、冰寒於水、木受繩、金就礪作喻，說明學習能改變和提升人。"},{"label":"第二段","summary":"以「思」與「學」、「跂望」與「登高」對比，以及登高而招、順風而呼、假輿馬、假舟楫等例子，說明君子善於借助外物（學習）而超越常人。"},{"label":"第三段","summary":"以積土成山、積水成淵說明學習貴在積累；以騏驥與駑馬、鍥而舍之與鍥而不舍說明要堅持不懈；以螾與蟹對比，說明學習要專心一致。"}]'::jsonb, '本文勉勵人不斷學習：學習可以改變人的本性、使人「知明而行無過」；學習要善於借助外物，並且要不斷積累、堅持不懈、專心一致。', '[{"name":"比喻論證","detail":"全文大量運用比喻，如以「青出於藍」「冰寒於水」比喻學習使人超越本來的自己，以「輮以為輪」比喻學習改變本性。"},{"name":"對比論證","detail":"「騏驥一躍」與「駑馬十駕」、「鍥而舍之」與「鍥而不舍」、「螾」與「蟹」正反對比，突出積累、堅持和專一的重要。"},{"name":"排比","detail":"「積土成山……積水成淵……積善成德」以排比層層推進，由自然現象引出道德修養，氣勢充沛。"},{"name":"對偶","detail":"「登高而招……順風而呼」「假輿馬者……假舟楫者」句式工整，節奏鏗鏘。"},{"name":"層層推進的結構","detail":"由「為何要學」（學習的重要）到「學習的作用」（善假於物），再到「怎樣學」（積累、堅持、專一），條理清晰。"}]'::jsonb, '["必背中心論點：「學不可以已」；第二段結論：「君子生非異也，善假於物也」。","第三段三個學習態度：積累（積土成山）、堅持（鍥而不舍）、專一（用心一也）。","通假字：輮（煣，使彎曲）、有（又）、知（智）、生（性）。"]'::jsonb),
  ('lianpo', 5, '廉頗藺相如列傳（節錄）', '司馬遷', '西漢', '《史記》', '史傳（紀傳體）', '司馬遷，字子長，西漢史學家、文學家。《史記》是中國第一部紀傳體通史。節錄部分記述藺相如「完璧歸趙」「澠池之會」，以及廉頗「負荊請罪」三件事，刻畫藺相如的智勇和以國家為重的胸襟，以及廉頗知錯能改的性格。', '[{"heading":null,"paragraphs":["廉頗者，趙之良將也。趙惠文王十六年，廉頗為趙將伐齊，大破之，取陽晉，拜為上卿，以勇氣聞於諸侯。藺相如者，趙人也，為趙宦者令繆賢舍人。","趙惠文王時，得楚和氏璧。秦昭王聞之，使人遺趙王書，願以十五城請易璧。趙王與大將軍廉頗諸大臣謀：欲予秦，秦城恐不可得，徒見欺；欲勿予，即患秦兵之來。計未定，求人可使報秦者，未得。宦者令繆賢曰：「臣舍人藺相如可使。」王問：「何以知之？」對曰：「臣嘗有罪，竊計欲亡走燕，臣舍人相如止臣，曰：『君何以知燕王？』臣語曰：『臣嘗從大王與燕王會境上，燕王私握臣手，曰：「願結友。」以此知之，故欲往。』相如謂臣曰：『夫趙強而燕弱，而君幸於趙王，故燕王欲結於君。今君乃亡趙走燕，燕畏趙，其勢必不敢留君，而束君歸趙矣。君不如肉袒伏斧質請罪，則幸得脫矣。』臣從其計，大王亦幸赦臣。臣竊以為其人勇士，有智謀，宜可使。」","於是王召見，問藺相如曰：「秦王以十五城請易寡人之璧，可予不？」相如曰：「秦強而趙弱，不可不許。」王曰：「取吾璧，不予我城，奈何？」相如曰：「秦以城求璧而趙不許，曲在趙；趙予璧而秦不予趙城，曲在秦。均之二策，寧許以負秦曲。」王曰：「誰可使者？」相如曰：「王必無人，臣願奉璧往使。城入趙而璧留秦；城不入，臣請完璧歸趙。」趙王於是遂遣相如奉璧西入秦。","秦王坐章臺見相如，相如奉璧奏秦王。秦王大喜，傳以示美人及左右，左右皆呼萬歲。相如視秦王無意償趙城，乃前曰：「璧有瑕，請指示王。」王授璧，相如因持璧卻立，倚柱，怒髮上衝冠，謂秦王曰：「大王欲得璧，使人發書至趙王，趙王悉召群臣議，皆曰：『秦貪，負其強，以空言求璧，償城恐不可得。』議不欲予秦璧。臣以為布衣之交尚不相欺，況大國乎！且以一璧之故逆強秦之驩，不可。於是趙王乃齋戒五日，使臣奉璧，拜送書於庭。何者？嚴大國之威以修敬也。今臣至，大王見臣列觀，禮節甚倨；得璧，傳之美人，以戲弄臣。臣觀大王無意償趙王城邑，故臣復取璧。大王必欲急臣，臣頭今與璧俱碎於柱矣！」相如持其璧睨柱，欲以擊柱。秦王恐其破璧，乃辭謝，固請，召有司案圖，指從此以往十五都予趙。","相如度秦王特以詐詳為予趙城，實不可得，乃謂秦王曰：「和氏璧，天下所共傳寶也。趙王恐，不敢不獻。趙王送璧時，齋戒五日。今大王亦宜齋戒五日，設九賓於廷，臣乃敢上璧。」秦王度之，終不可強奪，遂許齋五日，舍相如廣成傳舍。相如度秦王雖齋，決負約不償城，乃使其從者衣褐，懷其璧，從徑道亡，歸璧於趙。","秦王齋五日後，乃設九賓禮於廷，引趙使者藺相如。相如至，謂秦王曰：「秦自繆公以來二十餘君，未嘗有堅明約束者也。臣誠恐見欺於王而負趙，故令人持璧歸，間至趙矣。且秦強而趙弱，大王遣一介之使至趙，趙立奉璧來。今以秦之強而先割十五都予趙，趙豈敢留璧而得罪於大王乎？臣知欺大王之罪當誅，臣請就湯鑊。唯大王與群臣孰計議之。」秦王與群臣相視而嘻。左右或欲引相如去，秦王因曰：「今殺相如，終不能得璧也，而絕秦趙之驩。不如因而厚遇之，使歸趙。趙王豈以一璧之故欺秦邪！」卒廷見相如，畢禮而歸之。","相如既歸，趙王以為賢大夫，使不辱於諸侯，拜相如為上大夫。秦亦不以城予趙，趙亦終不予秦璧。","其後秦伐趙，拔石城。明年，復攻趙，殺二萬人。","秦王使使者告趙王，欲與王為好，會於西河外澠池。趙王畏秦，欲毋行。廉頗、藺相如計曰：「王不行，示趙弱且怯也。」趙王遂行，相如從。廉頗送至境，與王訣曰：「王行，度道里會遇之禮畢，還，不過三十日。三十日不還，則請立太子為王，以絕秦望。」王許之，遂與秦王會澠池。秦王飲酒酣，曰：「寡人竊聞趙王好音，請奏瑟。」趙王鼓瑟。秦御史前書曰：「某年月日，秦王與趙王會飲，令趙王鼓瑟。」藺相如前曰：「趙王竊聞秦王善為秦聲，請奏盆缻秦王，以相娛樂。」秦王怒，不許。於是相如前進缻，因跪請秦王。秦王不肯擊缻。相如曰：「五步之內，相如請得以頸血濺大王矣！」左右欲刃相如，相如張目叱之，左右皆靡。於是秦王不懌，為一擊缻。相如顧召趙御史書曰：「某年月日，秦王為趙王擊缻。」秦之群臣曰：「請以趙十五城為秦王壽。」藺相如亦曰：「請以秦之咸陽為趙王壽。」秦王竟酒，終不能加勝於趙。趙亦盛設兵以待秦，秦不敢動。","既罷，歸國，以相如功大，拜為上卿，位在廉頗之右。廉頗曰：「我為趙將，有攻城野戰之大功，而藺相如徒以口舌為勞，而位居我上。且相如素賤人，吾羞，不忍為之下。」宣言曰：「我見相如，必辱之。」相如聞，不肯與會。相如每朝時，常稱病，不欲與廉頗爭列。已而相如出，望見廉頗，相如引車避匿。於是舍人相與諫曰：「臣所以去親戚而事君者，徒慕君之高義也。今君與廉頗同列，廉君宣惡言，而君畏匿之，恐懼殊甚。且庸人尚羞之，況於將相乎！臣等不肖，請辭去。」藺相如固止之，曰：「公之視廉將軍孰與秦王？」曰：「不若也。」相如曰：「夫以秦王之威，而相如廷叱之，辱其群臣，相如雖駑，獨畏廉將軍哉？顧吾念之，強秦之所以不敢加兵於趙者，徒以吾兩人在也。今兩虎共鬥，其勢不俱生。吾所以為此者，以先國家之急而後私讎也。」廉頗聞之，肉袒負荊，因賓客至藺相如門謝罪，曰：「鄙賤之人，不知將軍寬之至此也。」卒相與驩，為刎頸之交。"]}]'::jsonb, '[{"label":"人物介紹","summary":"簡介廉頗是勇武的良將，藺相如出身低微，只是宦者令的門客。"},{"label":"完璧歸趙（起因）","summary":"秦以十五城換和氏璧，趙國兩難；繆賢以藺相如勸自己請罪一事，推薦他有智勇。"},{"label":"完璧歸趙（定策）","summary":"相如分析「曲在秦」，主動請纓奉璧入秦，承諾「完璧歸趙」。"},{"label":"完璧歸趙（章臺）","summary":"秦王無意償城，相如藉口璧有瑕取回璧，以頭與璧俱碎相脅，迫秦王案圖劃城。"},{"label":"完璧歸趙（周旋）","summary":"相如要求秦王齋戒五日，暗中派從者把璧送回趙國。"},{"label":"完璧歸趙（廷見）","summary":"相如坦承送璧回國，據理力陳，請就湯鑊；秦王權衡後厚待並送他回國。"},{"label":"完璧歸趙（結果）","summary":"相如出使不辱，拜為上大夫；秦趙均未交換城與璧。"},{"label":"過渡","summary":"秦國其後兩度攻趙，為澠池之會作鋪墊。"},{"label":"澠池之會","summary":"秦王令趙王鼓瑟以辱趙，相如以死相逼，迫秦王擊缻，又以「咸陽為趙王壽」反擊，使秦「終不能加勝於趙」。"},{"label":"將相和","summary":"相如位在廉頗之上，廉頗不服；相如以國家為先，處處退讓。廉頗得知後負荊請罪，二人成為刎頸之交。"}]'::jsonb, '本文透過「完璧歸趙」「澠池之會」「負荊請罪」三個故事，表現藺相如智勇雙全、不畏強權、先國家之急而後私讎的品格，以及廉頗知錯能改、勇於認錯的胸襟，突顯將相和睦、以國家利益為重的精神。', '[{"name":"以言行刻畫人物","detail":"藺相如「持璧卻立，倚柱，怒髮上衝冠」「張目叱之」等動作描寫，以及「臣頭今與璧俱碎於柱矣」等語言描寫，生動表現其勇氣與機智。"},{"name":"對比","detail":"相如在秦王面前剛強不屈，在廉頗面前卻處處退讓，對比之下突顯他「先國家之急而後私讎」的胸襟；秦王的倨傲與相如的不卑不亢亦形成對比。"},{"name":"側面描寫（襯托）","detail":"借繆賢的推薦、舍人的諫言和廉頗的不服，從側面襯托相如的智勇與器量。"},{"name":"情節跌宕、詳略得當","detail":"完璧歸趙一節多次轉折（獻璧、奪璧、齋戒、送璧、廷見），扣人心弦；次要事件如秦伐趙則一筆帶過。"},{"name":"互見與伏筆","detail":"開首交代廉頗「以勇氣聞於諸侯」及相如身份低微，為後文廉頗不服相如埋下伏筆。"}]'::jsonb, '["能按三個事件歸納藺相如的性格：智（分析曲直、齋戒拖延）、勇（以死相脅）、忠（先國家之急）。","廉頗的形象：恃功自傲 → 知錯能改。","通假字及異體字：「詐詳」的「詳」通「佯」；「缻」同「缶」；「驩」同「歡」；「可予不」的「不」通「否」。"]'::jsonb),
  ('chushi', 6, '出師表', '諸葛亮', '三國・蜀漢', '《三國志・蜀書・諸葛亮傳》', '奏議（表）', '諸葛亮，字孔明，三國時蜀漢丞相。建興五年（227年），諸葛亮準備北伐曹魏，臨行前向後主劉禪上此表，勸勉後主親賢遠佞，並表明自己報答先帝、興復漢室的決心。', '[{"heading":null,"paragraphs":["臣亮言：先帝創業未半，而中道崩殂；今天下三分，益州疲弊，此誠危急存亡之秋也。然侍衛之臣，不懈於內；忠志之士，忘身於外者，蓋追先帝之殊遇，欲報之於陛下也。誠宜開張聖聽，以光先帝遺德，恢弘志士之氣；不宜妄自菲薄，引喻失義，以塞忠諫之路也。","宮中府中，俱為一體，陟罰臧否，不宜異同。若有作姦犯科，及為忠善者，宜付有司，論其刑賞，以昭陛下平明之理；不宜偏私，使內外異法也。","侍中、侍郎郭攸之、費禕、董允等，此皆良實，志慮忠純，是以先帝簡拔以遺陛下。愚以為宮中之事，事無大小，悉以咨之，然後施行，必能裨補闕漏，有所廣益。將軍向寵，性行淑均，曉暢軍事，試用於昔日，先帝稱之曰「能」，是以眾議舉寵為督。愚以為營中之事，悉以咨之，必能使行陣和睦，優劣得所。","親賢臣，遠小人，此先漢所以興隆也；親小人，遠賢臣，此後漢所以傾頹也。先帝在時，每與臣論此事，未嘗不歎息痛恨於桓、靈也。侍中、尚書、長史、參軍，此悉貞良死節之臣，願陛下親之、信之，則漢室之隆，可計日而待也。","臣本布衣，躬耕於南陽，苟全性命於亂世，不求聞達於諸侯。先帝不以臣卑鄙，猥自枉屈，三顧臣於草廬之中，諮臣以當世之事，由是感激，遂許先帝以驅馳。後值傾覆，受任於敗軍之際，奉命於危難之間，爾來二十有一年矣。","先帝知臣謹慎，故臨崩寄臣以大事也。受命以來，夙夜憂歎，恐託付不效，以傷先帝之明。故五月渡瀘，深入不毛。今南方已定，兵甲已足，當獎率三軍，北定中原，庶竭駑鈍，攘除姦兇，興復漢室，還於舊都。此臣所以報先帝而忠陛下之職分也。至於斟酌損益，進盡忠言，則攸之、禕、允之任也。","願陛下託臣以討賊興復之效；不效，則治臣之罪，以告先帝之靈。若無興德之言，則責攸之、禕、允等之慢，以彰其咎。陛下亦宜自謀，以諮諏善道，察納雅言，深追先帝遺詔。臣不勝受恩感激。","今當遠離，臨表涕零，不知所言。"]}]'::jsonb, '[{"label":"第一段","summary":"分析形勢危急，指出臣子盡忠是為報先帝之恩；建議後主廣開言路。"},{"label":"第二段","summary":"建議賞罰嚴明，宮中府中一視同仁。"},{"label":"第三段","summary":"推薦郭攸之、費禕、董允主理宮中事務，向寵主理軍事。"},{"label":"第四段","summary":"以先漢興隆、後漢傾頹為鑑，勸後主親賢臣、遠小人。"},{"label":"第五段","summary":"自述出身及先帝三顧草廬的知遇之恩，受命於危難之間。"},{"label":"第六段","summary":"交代受託孤後的努力（南征），表明北伐、興復漢室的決心。"},{"label":"第七段","summary":"提出分工與責任，請後主自謀、納諫，追念先帝遺詔。"},{"label":"第八段","summary":"臨別表達感激涕零之情。"}]'::jsonb, '本文向後主提出廣開言路、賞罰分明、親賢遠佞三項建議，並追述先帝知遇之恩，表達自己報答先帝、忠於後主、北伐中原以興復漢室的決心，充分體現諸葛亮的忠貞與憂國之情。', '[{"name":"情理兼備","detail":"前半部分以理勸諫（三項建議），後半部分以情動人（追述先帝知遇之恩），情與理互相配合，使後主易於接受。"},{"name":"對比","detail":"「親賢臣，遠小人，此先漢所以興隆也；親小人，遠賢臣，此後漢所以傾頹也」以正反對比說明用人得失，引以為鑑。"},{"name":"多次提及「先帝」","detail":"全文十多次提及先帝，借先帝的權威和恩情勸勉後主，並表明自己的忠誠，語氣委婉懇切。"},{"name":"對偶","detail":"「侍衛之臣，不懈於內；忠志之士，忘身於外」「受任於敗軍之際，奉命於危難之間」句式工整，增強節奏感。"},{"name":"以敘事抒情","detail":"自述躬耕南陽、三顧草廬、受任敗軍等經歷，於敘事中流露感恩與忠誠。"}]'::jsonb, '["三項建議：開張聖聽、陟罰臧否不宜異同、親賢遠佞。","注意文中「先帝」與「陛下」的關係，分析作者勸諫的語氣（既是臣子又是託孤長輩）。","常考字詞：秋（時候）、卑鄙（地位低微、見識淺陋，古今異義）、感激（感動奮發，古今異義）、遺（給予）。"]'::jsonb),
  ('shishuo', 7, '師說', '韓愈', '唐', '《昌黎先生集》', '議論文（說）', '韓愈，字退之，唐代文學家，古文運動領袖，「唐宋八大家」之首。當時士大夫恥於從師，韓愈寫本文贈予好學的弟子李蟠，闡述從師的必要和擇師的標準，批評恥於從師的風氣。', '[{"heading":null,"paragraphs":["古之學者必有師。師者，所以傳道、受業、解惑也。人非生而知之者，孰能無惑？惑而不從師，其為惑也，終不解矣。生乎吾前，其聞道也，固先乎吾，吾從而師之；生乎吾後，其聞道也，亦先乎吾，吾從而師之。吾師道也，夫庸知其年之先後生於吾乎？是故無貴無賤，無長無少，道之所存，師之所存也。","嗟乎！師道之不傳也久矣！欲人之無惑也難矣！古之聖人，其出人也遠矣，猶且從師而問焉；今之眾人，其下聖人也亦遠矣，而恥學於師。是故聖益聖，愚益愚。聖人之所以為聖，愚人之所以為愚，其皆出於此乎！愛其子，擇師而教之；於其身也，則恥師焉，惑矣！彼童子之師，授之書而習其句讀者，非吾所謂傳其道、解其惑者也。句讀之不知，惑之不解，或師焉，或不焉，小學而大遺，吾未見其明也。巫醫、樂師、百工之人，不恥相師；士大夫之族，曰師、曰弟子云者，則群聚而笑之。問之，則曰：「彼與彼年相若也，道相似也。位卑則足羞，官盛則近諛。」嗚呼！師道之不復，可知矣。巫醫、樂師、百工之人，君子不齒，今其智乃反不能及，其可怪也歟！","聖人無常師。孔子師郯子、萇弘、師襄、老聃。郯子之徒，其賢不及孔子。孔子曰：「三人行，則必有我師。」是故弟子不必不如師，師不必賢於弟子。聞道有先後，術業有專攻，如是而已。","李氏子蟠，年十七，好古文，六藝經傳，皆通習之，不拘於時，學於余。余嘉其能行古道，作《師說》以貽之。"]}]'::jsonb, '[{"label":"第一段","summary":"提出中心論點「古之學者必有師」，說明老師的職責（傳道、受業、解惑），以及擇師標準：「道之所存，師之所存」。"},{"label":"第二段","summary":"慨歎師道不傳，以三組對比批評時人恥於從師：古之聖人與今之眾人、為子擇師與自身恥師、百工之人與士大夫之族。"},{"label":"第三段","summary":"以孔子從師為例，說明「聖人無常師」，師生關係只在於「聞道有先後，術業有專攻」。"},{"label":"第四段","summary":"交代寫作緣由：嘉許李蟠能行古道，作本文相贈。"}]'::jsonb, '本文闡述從師學習的必要和擇師的標準，指出「道之所存，師之所存」，批評當時士大夫恥於從師的不良風氣，倡導尊師重道。', '[{"name":"對比論證","detail":"第二段以「古之聖人」與「今之眾人」、「愛其子」與「於其身」、「巫醫樂師百工之人」與「士大夫之族」三組對比，批評恥於從師的風氣，說服力強。"},{"name":"舉例論證","detail":"以孔子師郯子、萇弘、師襄、老聃為例，證明「聖人無常師」。"},{"name":"引用論證","detail":"引用孔子「三人行，則必有我師」，加強論點的權威性。"},{"name":"正反論證","detail":"先正面指出從師的必要，再從反面說明不從師則「終不解矣」。"},{"name":"感歎句、反問句","detail":"「嗟乎！師道之不傳也久矣！」「嗚呼！師道之不復，可知矣」等感歎，以及「孰能無惑？」的反問，增強感情色彩。"}]'::jsonb, '["老師的三項職責：傳道、受業、解惑。","擇師標準：無貴無賤，無長無少，道之所存，師之所存也。","第二段三組對比是必考內容；留意「受」通「授」、「不」通「否」、「句讀」的讀音（dòu）。"]'::jsonb),
  ('xishan', 8, '始得西山宴遊記', '柳宗元', '唐', '《柳河東集》', '遊記', '柳宗元，字子厚，唐代文學家，「唐宋八大家」之一。他因參與「永貞革新」失敗，被貶為永州司馬。本文是「永州八記」的第一篇，記述作者初遊西山的經過和感受。', '[{"heading":null,"paragraphs":["自余為僇人，居是州，恆惴慄。其隙也，則施施而行，漫漫而遊。日與其徒上高山，入深林，窮迴谿，幽泉怪石，無遠不到。到則披草而坐，傾壺而醉；醉則更相枕以臥，臥而夢。意有所極，夢亦同趣。覺而起，起而歸。以為凡是州之山水有異態者，皆我有也，而未始知西山之怪特。","今年九月二十八日，因坐法華西亭，望西山，始指異之。遂命僕人過湘江，緣染溪，斫榛莽，焚茅茷，窮山之高而止。攀援而登，箕踞而遨，則凡數州之土壤，皆在衽席之下。其高下之勢，岈然窪然，若垤若穴，尺寸千里，攢蹙累積，莫得遯隱。縈青繚白，外與天際，四望如一。然後知是山之特立，不與培塿為類。悠悠乎與灝氣俱，而莫得其涯；洋洋乎與造物者遊，而不知其所窮。引觴滿酌，頹然就醉，不知日之入。蒼然暮色，自遠而至，至無所見，而猶不欲歸。心凝形釋，與萬化冥合。然後知吾嚮之未始遊，遊於是乎始，故為之文以志。是歲，元和四年也。"]}]'::jsonb, '[{"label":"第一段","summary":"記述被貶永州後內心惶恐，借遊山玩水排遣；自以為遊遍永州山水，卻「未始知西山之怪特」。"},{"label":"第二段","summary":"記初遊西山經過：開路登頂，俯瞰群山如蟻垤洞穴，體會西山「特立」「不與培塿為類」；沉醉至暮色降臨，達到「心凝形釋，與萬化冥合」的境界，領悟此前未曾真正遊覽。"}]'::jsonb, '本文記述作者初遊西山的經過和感受，藉描寫西山的高峻特立，寄託自己不肯與世俗小人同流合污的孤高情懷，並抒發在山水中暫時忘卻貶謫之苦、物我合一的精神解脫。', '[{"name":"托物言志","detail":"以西山「特立，不與培塿為類」自比，寄託作者孤高傲世、不與小人為伍的志節。"},{"name":"對比／襯托","detail":"以第一段漫遊群山的「無遠不到」襯托西山的「怪特」；以群山「若垤若穴」襯托西山之高。"},{"name":"情景交融","detail":"由「恆惴慄」到「心凝形釋，與萬化冥合」，景物描寫與心境變化互相映照。"},{"name":"前後呼應、扣題","detail":"首段「未始知西山之怪特」與結尾「然後知吾嚮之未始遊，遊於是乎始」呼應，緊扣題目「始得」二字。"},{"name":"頂真","detail":"「到則披草而坐，傾壺而醉；醉則更相枕以臥，臥而夢……覺而起，起而歸」以頂真句式寫出百無聊賴、隨意漫遊的狀態。"}]'::jsonb, '["題目「始得」的意思：初次發現、真正領略西山之美，並暗示作者心境的轉變。","比較兩段的遊覽心情：第一段「恆惴慄」、漫無目的；第二段「心凝形釋」、物我合一。","常考字詞：僇人（罪人）、恆（經常）、施施（緩慢行走的樣子）、窮（盡）、志（記）、嚮（從前，通「向」）。"]'::jsonb),
  ('yueyang', 9, '岳陽樓記', '范仲淹', '北宋', '《范文正公集》', '記（亭臺樓閣記）', '范仲淹，字希文，北宋政治家、文學家。慶曆新政失敗後，范仲淹被貶鄧州。好友滕子京重修岳陽樓，請他作記。作者借記樓抒懷，提出「先天下之憂而憂，後天下之樂而樂」的抱負。', '[{"heading":null,"paragraphs":["慶曆四年春，滕子京謫守巴陵郡。越明年，政通人和，百廢具興。乃重修岳陽樓，增其舊制，刻唐賢今人詩賦於其上，屬予作文以記之。","予觀夫巴陵勝狀，在洞庭一湖。銜遠山，吞長江，浩浩湯湯，橫無際涯；朝暉夕陰，氣象萬千。此則岳陽樓之大觀也，前人之述備矣。然則北通巫峽，南極瀟湘，遷客騷人，多會於此，覽物之情，得無異乎？","若夫霪雨霏霏，連月不開；陰風怒號，濁浪排空；日星隱耀，山岳潛形；商旅不行，檣傾楫摧；薄暮冥冥，虎嘯猿啼。登斯樓也，則有去國懷鄉，憂讒畏譏，滿目蕭然，感極而悲者矣。","至若春和景明，波瀾不驚，上下天光，一碧萬頃；沙鷗翔集，錦鱗游泳；岸芷汀蘭，郁郁青青。而或長煙一空，皓月千里，浮光躍金，靜影沈璧；漁歌互答，此樂何極！登斯樓也，則有心曠神怡，寵辱偕忘，把酒臨風，其喜洋洋者矣。","嗟夫！予嘗求古仁人之心，或異二者之為，何哉？不以物喜，不以己悲。居廟堂之高，則憂其民；處江湖之遠，則憂其君。是進亦憂，退亦憂；然則何時而樂耶？其必曰：「先天下之憂而憂，後天下之樂而樂」歟！噫！微斯人，吾誰與歸！","時六年九月十五日。"]}]'::jsonb, '[{"label":"第一段","summary":"交代作記緣由：滕子京謫守巴陵，政績卓著，重修岳陽樓並囑作者作記。"},{"label":"第二段","summary":"概寫洞庭湖的壯闊景象，帶出遷客騷人「覽物之情，得無異乎」的問題。"},{"label":"第三段","summary":"寫陰雨時的悲涼景色，以及遷客騷人「感極而悲」的心情。"},{"label":"第四段","summary":"寫春和景明時的明媚景色，以及遷客騷人「其喜洋洋」的心情。"},{"label":"第五段","summary":"提出古仁人「不以物喜，不以己悲」，進退皆憂，「先天下之憂而憂，後天下之樂而樂」的胸懷，表明願與之同道。"},{"label":"第六段","summary":"交代寫作日期。"}]'::jsonb, '本文借記重修岳陽樓，通過遷客騷人因景物變化而或悲或喜，與古仁人「不以物喜，不以己悲」對比，抒發作者「先天下之憂而憂，後天下之樂而樂」的政治抱負，並勉勵被貶的滕子京。', '[{"name":"借景抒情","detail":"第三、四段分寫陰雨與晴明的景色，帶出遷客騷人的悲與喜，情景交融。"},{"name":"對比","detail":"陰雨之景與晴明之景對比；遷客騷人「以物喜，以己悲」與古仁人「不以物喜，不以己悲」對比，突出主旨。"},{"name":"駢散結合","detail":"大量運用四字句和對偶（如「銜遠山，吞長江」「沙鷗翔集，錦鱗游泳」），又配合散句，音韻和諧、節奏明快。"},{"name":"由敘事、寫景到議論的結構","detail":"由記事（重修樓）→ 寫景（洞庭湖）→ 抒情（覽物之悲喜）→ 議論（古仁人之心），層層推進，最後點出主旨。"},{"name":"設問","detail":"「覽物之情，得無異乎？」「然則何時而樂耶？」以設問引出下文，帶動行文。"}]'::jsonb, '["必背主旨句：「不以物喜，不以己悲」「先天下之憂而憂，後天下之樂而樂」。","比較第三、四段的景物描寫與情感（悲 vs 喜）。","常考字詞：具（全，通「俱」）、屬（囑咐，通「囑」）、微（如果沒有）、斯人（指古仁人）、歸（歸依、同道）。"]'::jsonb),
  ('liuguo', 10, '六國論', '蘇洵', '北宋', '《嘉祐集》', '史論（議論文）', '蘇洵，字明允，號老泉，北宋文學家，與子蘇軾、蘇轍合稱「三蘇」，同列「唐宋八大家」。北宋對遼和西夏採取納幣求和的政策，蘇洵借評論六國破滅的原因，諷諭北宋朝廷。', '[{"heading":null,"paragraphs":["六國破滅，非兵不利，戰不善，弊在賂秦。賂秦而力虧，破滅之道也。或曰：「六國互喪，率賂秦耶？」曰：「不賂者以賂者喪。蓋失強援，不能獨完。故曰：弊在賂秦也。」","秦以攻取之外，小則獲邑，大則得城。較秦之所得，與戰勝而得者，其實百倍；諸侯之所亡，與戰敗而亡者，其實亦百倍。則秦之大欲，諸侯之大患，固不在戰矣。思厥先祖父，暴霜露，斬荊棘，以有尺寸之地。子孫視之不甚惜，舉以予人，如棄草芥。今日割五城，明日割十城，然後得一夕安寢。起視四境，而秦兵又至矣。然則諸侯之地有限，暴秦之欲無厭，奉之彌繁，侵之愈急。故不戰而強弱勝負已判矣。至於顛覆，理固宜然。古人云：「以地事秦，猶抱薪救火，薪不盡，火不滅。」此言得之。","齊人未嘗賂秦，終繼五國遷滅，何哉？與嬴而不助五國也。五國既喪，齊亦不免矣。燕、趙之君，始有遠略，能守其土，義不賂秦。是故燕雖小國而後亡，斯用兵之效也。至丹以荊卿為計，始速禍焉。趙嘗五戰於秦，二敗而三勝。後秦擊趙者再，李牧連卻之。洎牧以讒誅，邯鄲為郡，惜其用武而不終也。且燕、趙處秦革滅殆盡之際，可謂智力孤危，戰敗而亡，誠不得已。向使三國各愛其地，齊人勿附於秦，刺客不行，良將猶在，則勝負之數，存亡之理，當與秦相較，或未易量。","嗚呼！以賂秦之地，封天下之謀臣；以事秦之心，禮天下之奇才，并力西嚮，則吾恐秦人食之不得下咽也。悲夫！有如此之勢，而為秦人積威之所劫，日削月割，以趨於亡。為國者無使為積威之所劫哉！","夫六國與秦皆諸侯，其勢弱於秦，而猶有可以不賂而勝之之勢；苟以天下之大，而從六國破亡之故事，是又在六國下矣。"]}]'::jsonb, '[{"label":"第一段","summary":"提出中心論點：六國破滅「弊在賂秦」；並分兩個分論點：賂秦者「力虧」而亡，不賂者因「失強援」而亡。"},{"label":"第二段","summary":"論證賂秦者之亡：秦以賄賂所得遠多於戰勝所得；諸侯割地求安，「奉之彌繁，侵之愈急」，引「抱薪救火」作結。"},{"label":"第三段","summary":"論證不賂者之亡：齊附秦而不助五國；燕、趙本能抗秦，卻因刺秦、誅李牧而亡；假設三國不賂、良將猶在，勝負未可知。"},{"label":"第四段","summary":"設想若以賂秦之地封謀臣、禮奇才，合力抗秦，秦必難以得逞；慨歎六國為秦積威所劫，告誡為國者。"},{"label":"第五段","summary":"借古諷今：北宋以天下之大而重蹈六國賂敵覆轍，則連六國也不如。"}]'::jsonb, '本文借論六國破滅的原因在於「賂秦」，諷諭北宋朝廷向遼和西夏納幣求和的屈辱政策，告誡當權者不可為敵人積威所劫，應奮發圖強、抗敵禦侮。', '[{"name":"借古諷今","detail":"表面評論六國歷史，結尾點出「苟以天下之大，而從六國破亡之故事，是又在六國下矣」，諷刺北宋對外妥協。"},{"name":"總分結構、論點清晰","detail":"首段提出總論點及兩個分論點，第二、三段分別論證，層次分明。"},{"name":"對比論證","detail":"「秦之所得」與「戰勝而得者」、「諸侯之所亡」與「戰敗而亡者」對比；「暴霜露，斬荊棘」的先祖與「如棄草芥」的子孫對比。"},{"name":"引用及比喻論證","detail":"引古人「以地事秦，猶抱薪救火」，以抱薪救火比喻割地事秦只會加速滅亡。"},{"name":"假設論證","detail":"「向使三國各愛其地……或未易量」「以賂秦之地，封天下之謀臣……」以假設推論，增強說服力。"}]'::jsonb, '["必背論點：「六國破滅，非兵不利，戰不善，弊在賂秦。」","分論點：「賂秦而力虧」與「不賂者以賂者喪」。","常考字詞：率（全都）、完（保全）、厥（其，他們的）、暴（曝曬）、判（分出、決定）、洎（等到）。"]'::jsonb),
  ('shi3', 11, '詩三首', '王維、李白、杜甫', '唐', '《王右丞集》《李太白全集》《杜工部集》', '近體詩／古體詩', '選錄唐代三位大詩人的作品：王維〈山居秋暝〉（五言律詩）、李白〈月下獨酌〉（其一，五言古詩）、杜甫〈登樓〉（七言律詩），分別展現山水田園的閒適、浪漫豪放的孤獨與沉鬱頓挫的憂國情懷。', '[{"heading":"山居秋暝　王維","paragraphs":["空山新雨後，天氣晚來秋。","明月松間照，清泉石上流。","竹喧歸浣女，蓮動下漁舟。","隨意春芳歇，王孫自可留。"]},{"heading":"月下獨酌（其一）　李白","paragraphs":["花間一壺酒，獨酌無相親。","舉杯邀明月，對影成三人。","月既不解飲，影徒隨我身。","暫伴月將影，行樂須及春。","我歌月徘徊，我舞影零亂。","醒時同交歡，醉後各分散。","永結無情遊，相期邈雲漢。"]},{"heading":"登樓　杜甫","paragraphs":["花近高樓傷客心，萬方多難此登臨。","錦江春色來天地，玉壘浮雲變古今。","北極朝廷終不改，西山寇盜莫相侵。","可憐後主還祠廟，日暮聊為梁甫吟。"]}]'::jsonb, '[{"label":"山居秋暝","summary":"首聯點明雨後秋夕；頷聯寫明月清泉的靜景；頸聯寫浣女漁舟的動景；尾聯反用《楚辭》典故，表明願意留在山中。"},{"label":"月下獨酌","summary":"前四句寫花間獨酌，邀月與影成三人；中段寫月、影不解人意，仍及時行樂、歌舞同歡；結尾願與月、影永結忘情之交，相約於天上。"},{"label":"登樓","summary":"首聯寫國家多難時登樓傷心；頷聯寫錦江春色與玉壘浮雲，寄寓世事變幻；頸聯表達對朝廷的信心及對吐蕃的警告；尾聯借劉禪及〈梁甫吟〉，暗諷時君並抒發報國無門之歎。"}]'::jsonb, '〈山居秋暝〉描寫山居秋夜的清幽景色和淳樸生活，表達作者對隱居生活的喜愛和對官場的厭倦；〈月下獨酌〉寫詩人月下獨飲，以豪放的想像排遣孤獨寂寞，流露懷才不遇的苦悶；〈登樓〉寫詩人登樓所見所感，抒發憂國傷時之情及對國家前途的關切。', '[{"name":"動靜結合（山居秋暝）","detail":"「明月松間照，清泉石上流」寫靜景，「竹喧歸浣女，蓮動下漁舟」寫動景，以動襯靜，突出山居的幽靜。"},{"name":"先聞其聲後見其人（山居秋暝）","detail":"「竹喧」「蓮動」先寫聲響和動態，再交代浣女和漁舟，構思巧妙。"},{"name":"擬人與想像（月下獨酌）","detail":"把月和影擬人化，「舉杯邀明月，對影成三人」，以熱鬧反襯孤獨，浪漫奔放。"},{"name":"以樂景寫哀情（登樓）","detail":"「花近高樓」「錦江春色」是美景，卻「傷客心」，反襯詩人憂國之深。"},{"name":"用典（登樓）","detail":"以蜀後主劉禪的祠廟暗諷唐代宗寵信宦官；以諸葛亮喜吟的〈梁甫吟〉自況，抒發報國無門之情。"},{"name":"格律與對仗","detail":"〈山居秋暝〉〈登樓〉為律詩，頷聯和頸聯對仗工整；〈月下獨酌〉為古體詩，句數和押韻較自由。"}]'::jsonb, '["能辨別三首詩的體裁：五律、五古、七律。","比較三位詩人的風格：王維（詩中有畫、閒適）、李白（浪漫豪放）、杜甫（沉鬱頓挫）。","常考詞語：隨意（任憑）、歇（消散）、將（和、與）、及春（趁着春天）、邈（遙遠）、聊（姑且）。"]'::jsonb),
  ('ci3', 12, '詞三首', '蘇軾、李清照、辛棄疾', '宋', '《東坡樂府》《漱玉詞》《稼軒長短句》', '詞', '選錄宋代三位詞人的作品：蘇軾〈念奴嬌・赤壁懷古〉（豪放）、李清照〈聲聲慢〉（婉約）、辛棄疾〈青玉案・元夕〉（豪放詞人的婉約之作），分別抒發懷古傷今、亡國喪夫之痛及孤高自守之志。', '[{"heading":"念奴嬌・赤壁懷古　蘇軾","paragraphs":["大江東去，浪淘盡、千古風流人物。故壘西邊，人道是、三國周郎赤壁。亂石穿空，驚濤拍岸，捲起千堆雪。江山如畫，一時多少豪傑！","遙想公瑾當年，小喬初嫁了，雄姿英發。羽扇綸巾，談笑間、檣櫓灰飛煙滅。故國神遊，多情應笑我，早生華髮。人生如夢，一尊還酹江月。"]},{"heading":"聲聲慢　李清照","paragraphs":["尋尋覓覓，冷冷清清，淒淒慘慘戚戚。乍暖還寒時候，最難將息。三杯兩盞淡酒，怎敵他、晚來風急？雁過也，正傷心，卻是舊時相識。","滿地黃花堆積，憔悴損，如今有誰堪摘？守着窗兒，獨自怎生得黑？梧桐更兼細雨，到黃昏、點點滴滴。這次第，怎一個愁字了得！"]},{"heading":"青玉案・元夕　辛棄疾","paragraphs":["東風夜放花千樹，更吹落、星如雨。寶馬雕車香滿路。鳳簫聲動，玉壺光轉，一夜魚龍舞。","蛾兒雪柳黃金縷，笑語盈盈暗香去。眾裏尋他千百度，驀然回首，那人卻在，燈火闌珊處。"]}]'::jsonb, '[{"label":"念奴嬌・赤壁懷古","summary":"上片寫赤壁的雄奇景色，引出對三國豪傑的懷念；下片追想周瑜年少得志、從容破敵，再反觀自己早生華髮、功業未成，以「人生如夢」自我開解。"},{"label":"聲聲慢","summary":"上片以疊字開篇，寫乍暖還寒時借酒澆愁、見雁傷心；下片寫黃花憔悴、獨守窗前、梧桐細雨，層層堆疊愁緒，以「怎一個愁字了得」作結。"},{"label":"青玉案・元夕","summary":"上片極寫元宵夜燈火輝煌、車馬喧鬧的熱鬧場面；下片寫盛裝遊女笑語而過，詞人在人群中千百度尋覓「那人」，最終在燈火冷落處找到。"}]'::jsonb, '〈念奴嬌〉借赤壁懷古，抒發對周瑜等英雄的仰慕和自己年華老去、功業未成的感慨，最終以曠達自解；〈聲聲慢〉寫南渡後國破家亡、夫死流離的孤寂愁苦；〈青玉案〉借尋覓燈火闌珊處的「那人」，寄託作者不慕繁華、孤高自守的人格。', '[{"name":"情景交融、借景抒情（念奴嬌）","detail":"「亂石穿空，驚濤拍岸，捲起千堆雪」寫赤壁雄奇景色，為懷古抒情營造壯闊氣氛。"},{"name":"對比與襯托（念奴嬌）","detail":"以周瑜「雄姿英發」「談笑間、檣櫓灰飛煙滅」對比自己「早生華髮」，突出功業未成的感慨。"},{"name":"疊字（聲聲慢）","detail":"開首連用十四個疊字「尋尋覓覓，冷冷清清，淒淒慘慘戚戚」，由動作到環境到心情，層層深入，音韻低沉。"},{"name":"借物抒情（聲聲慢）","detail":"以淡酒、過雁、黃花、梧桐、細雨等意象，寄寓孤寂與哀愁。"},{"name":"以樂景襯哀情／反襯（青玉案）","detail":"上片極寫元夕的熱鬧繁華，反襯下片「那人」在「燈火闌珊處」的孤高冷清。"},{"name":"象徵（青玉案）","detail":"「那人」象徵作者不隨波逐流、甘於寂寞的高潔人格。"}]'::jsonb, '["分辨豪放（蘇軾、辛棄疾）與婉約（李清照）詞風，並留意〈青玉案〉是豪放詞人的婉約之作。","〈聲聲慢〉的疊字和「愁」的層層遞進是常考重點。","常考詞語：故壘（舊時營壘）、酹（以酒灑地祭奠）、將息（調養）、次第（光景、情形）、闌珊（零落、稀疏）。"]'::jsonb)
