  ('lunren-021', 'lunren', '論仁', '勿', '非禮勿視，非禮勿聽。', '不要', '副詞', array['一般']::text[], null, null),
  ('lunren-022', 'lunren', '論孝', '無違', '無違。', '不要違背（禮）', '詞組', array['一般']::text[], null, null),
