insert into public.practice_questions (id, fanwen_code, sort_order, qtype, prompt, options, answer, explanation, marks) values
  ('lunren-q1', 'lunren', 1, 'mc', '「君子無終食之間違仁，造次必於是，顛沛必於是。」這句話主要說明君子怎樣對待「仁」？', '["只在富貴時才實踐仁","任何時候、任何處境都不背離仁","在困頓時才需要仁","以仁換取名聲"]'::jsonb, 'B', '「無終食之間違仁」指連吃完一頓飯的時間也不離開仁；「造次」「顛沛」指倉卒和困頓之時，可見君子時刻不違仁。', 1),
  ('lunren-q2', 'lunren', 2, 'mc', '子游問孝時，孔子以「至於犬馬，皆能有養」說明甚麼？', '["子女應飼養寵物以娛親","供養父母比飼養犬馬更難","只供養而不敬重父母，與飼養犬馬無異","孝順就是讓父母吃得飽"]'::jsonb, 'C', '孔子指出犬馬也能得到飼養，若對父母只養不敬，便與養犬馬沒有分別，強調孝的核心在「敬」。', 1),
  ('lunren-q3', 'lunren', 3, 'mc', '下列哪一項與「君子求諸己，小人求諸人」的意思最接近？', '["君子凡事反躬自省，小人凡事責怪別人","君子向自己求取財富，小人向別人求取財富","君子不求人幫助，小人常常求人","君子和小人都應自求多福"]'::jsonb, 'A', '「求諸己」即要求自己、反省自己；「求諸人」即要求別人、歸咎別人。', 1),
  ('lunren-q4', 'lunren', 4, 'short', '孟懿子、子游和子夏同樣問孝，孔子的回答各有不同。試分別指出孔子三個回答的重點，並說明這反映孔子怎樣的教學方法。', null, '孟懿子：「無違」，即生、死、葬、祭都要合乎禮（1分）；子游：孝不止於能養，更要「敬」（1分）；子夏：「色難」，侍奉父母要保持和顏悅色（1分）。反映孔子因材施教，按發問者的不同情況給予不同答案（1分）。', '作答時宜引用原文關鍵詞，並清楚點出「因材施教」。', 4),
  ('lunren-q5', 'lunren', 5, 'short', '試從〈論君子〉選錄的章節中，舉出兩項君子與小人的分別，並引原文說明。', null, '①君子要求自己，小人要求別人：「君子求諸己，小人求諸人。」（2分）②君子成全別人的好事，不促成別人的壞事，小人相反：「君子成人之美，不成人之惡。小人反是。」（2分）', '每項：分別說明正確1分，引用原文正確1分。', 4),
  ('yuwo-q1', 'yuwo', 1, 'mc', '文章開首以「魚」和「熊掌」作喻，目的是甚麼？', '["說明熊掌比魚更美味","引出「生」與「義」不能兼得時應舍生取義","批評人們貪吃","說明人應知足"]'::jsonb, 'B', '以日常取捨作類比（比喻論證），引出中心論點「舍生而取義」。', 1),
  ('yuwo-q2', 'yuwo', 2, 'mc', '「鄉為身死而不受」中「鄉」字的意思是：', '["家鄉","從前","面向","鄉下人"]'::jsonb, 'B', '「鄉」通「嚮」，解作從前。', 1),
  ('yuwo-q3', 'yuwo', 3, 'mc', '作者認為「賢者」與一般人的分別在於：', '["賢者天生沒有欲望","賢者能保存人人皆有的本心","賢者比一般人更怕死","賢者從不接受施捨"]'::jsonb, 'B', '「非獨賢者有是心也，人皆有之，賢者能勿喪耳。」', 1),
  ('yuwo-q4', 'yuwo', 4, 'short', '第三段中，作者如何運用對比手法批評「失其本心」的人？試加以說明。', null, '作者先寫行道之人、乞人在生死關頭仍不肯接受無禮的施捨（1分），再寫有人為了萬鍾厚祿而「不辯禮義而受之」（1分）；又以「鄉為身死而不受」對比「今為宮室之美、妻妾之奉、所識窮乏者得我而為之」（1分），突出這些人為身外物而放棄禮義，比路人乞丐更不如，即「失其本心」（1分）。', '須指出對比雙方及其效果。', 4),
  ('yuwo-q5', 'yuwo', 5, 'short', '「是亦不可以已乎？」運用了甚麼修辭手法？有何作用？', null, '反問（1分）。以反問語氣表示這種做法難道不可以停止嗎（即應該停止）（1分），加強批判的力量，引人反思（1分）。', null, 3),
  ('xiaoyao-q1', 'xiaoyao', 1, 'mc', '惠子打破大瓠的原因是：', '["大瓠太重，搬不動","大瓠不堅固，容易破裂","大瓠雖大，卻無法盛水或作瓢，認為它無用","魏王命令他打破"]'::jsonb, 'C', '盛水則「其堅不能自舉」，作瓢則「瓠落無所容」，故「吾為其無用而掊之」。', 1),
  ('xiaoyao-q2', 'xiaoyao', 2, 'mc', '莊子以「不龜手之藥」的故事說明甚麼道理？', '["做生意要懂得討價還價","同一事物，用法不同，價值便大不相同","打仗要準備藥物","宋人世代勤勞值得學習"]'::jsonb, 'B', '「能不龜手，一也；或以封，或不免於洴澼絖，則所用之異也。」', 1),
  ('xiaoyao-q3', 'xiaoyao', 3, 'mc', '「則夫子猶有蓬之心也夫」中，「蓬之心」比喻：', '["心胸廣闊","心思閉塞、見識淺窄","心地善良","心情愉快"]'::jsonb, 'B', '蓬草彎曲不直，比喻惠子心思不通達、見識淺陋。', 1),
  ('xiaoyao-q4', 'xiaoyao', 4, 'short', '第二段中，莊子提及「狸狌」和「斄牛」，各有甚麼作用？', null, '狸狌靈巧有用，卻因此「中於機辟，死於罔罟」，說明有用反招禍害（2分）；斄牛雖大「若垂天之雲」，卻「不能執鼠」，說明大者不必用於小處，各有其用（2分）。兩者共同襯托大樹「無所可用」反能免禍、令人逍遙。', null, 4),
  ('xiaoyao-q5', 'xiaoyao', 5, 'short', '綜合兩段對話，試說明莊子「無用之用」的觀點。', null, '世俗以功利標準衡量事物是否有用（1分）；莊子認為事物的價值在於如何運用，大瓠可作大樽浮於江湖（1分）；看似無用的大樹反而不受斤斧之害，並可讓人逍遙其下，這正是「無用之用」（1分）。', null, 3),
  ('quanxue-q1', 'quanxue', 1, 'mc', '本文的中心論點是：', '["君子生非異也","學不可以已","用心一也","積善成德"]'::jsonb, 'B', '首句「君子曰：學不可以已」即全文中心論點。', 1),
  ('quanxue-q2', 'quanxue', 2, 'mc', '「假輿馬者，非利足也，而致千里」一句主要說明：', '["騎馬比走路快","善於借助外物，便能超越自身的限制","人應多做運動","千里之行始於足下"]'::jsonb, 'B', '本段結論是「君子生非異也，善假於物也」。', 1),
  ('quanxue-q3', 'quanxue', 3, 'mc', '作者以「螾」和「蟹」作對比，帶出哪種學習態度？', '["積累","堅持","專心一致","借助外物"]'::jsonb, 'C', '螾「用心一也」，蟹「用心躁也」，說明學習要專一。', 1),
  ('quanxue-q4', 'quanxue', 4, 'short', '第三段提出了哪三種學習態度？試各引一句原文說明。', null, '①積累：「積土成山……積善成德」或「不積跬步，無以至千里」；②堅持：「駑馬十駕，功在不舍」或「鍥而不舍，金石可鏤」；③專心：「螾……用心一也」。', '三項態度各1分；引文恰當另加1分（最多4分）。', 4),
  ('quanxue-q5', 'quanxue', 5, 'short', '「青，取之於藍，而青於藍；冰，水為之，而寒於水」運用了甚麼論證方法？說明了甚麼？', null, '比喻論證（1分）。以青出於藍而勝於藍、冰由水凝成而比水更寒（1分），比喻人通過學習可以超越原來的自己（1分）。', null, 3),
  ('lianpo-q1', 'lianpo', 1, 'mc', '繆賢推薦藺相如，主要因為：', '["相如是趙國貴族","相如曾勸他肉袒請罪，表現出智謀和勇氣","相如與秦王相熟","相如武藝高強"]'::jsonb, 'B', '繆賢憑相如勸他請罪一事，判斷「其人勇士，有智謀，宜可使」。', 1),
  ('lianpo-q2', 'lianpo', 2, 'mc', '「均之二策，寧許以負秦曲」的意思是：', '["兩個策略都不好，不如拒絕秦國","衡量兩個策略，寧可答應秦國，讓秦國承擔理虧的責任","兩個策略要平均使用","寧願背負罪名也要答應秦國"]'::jsonb, 'B', '「負」解作使……承擔；「曲」指理虧。', 1),
  ('lianpo-q3', 'lianpo', 3, 'mc', '藺相如對廉頗處處退讓，根本原因是：', '["害怕廉頗的武力","不屑與廉頗計較","先國家之急而後私讎","想討好趙王"]'::jsonb, 'C', '相如說：「吾所以為此者，以先國家之急而後私讎也。」', 1),
  ('lianpo-q4', 'lianpo', 4, 'short', '在「完璧歸趙」一事中，藺相如如何表現他的「智」和「勇」？試各舉一例說明。', null, '智：以「璧有瑕」為藉口取回和氏璧；或要求秦王齋戒五日，爭取時間派從者把璧送回趙國（2分）。勇：持璧倚柱，「怒髮上衝冠」，聲言「臣頭今與璧俱碎於柱矣」；或坦承已送璧回國，「請就湯鑊」（2分）。', null, 4),
  ('lianpo-q5', 'lianpo', 5, 'short', '作者如何刻畫廉頗的性格轉變？', null, '起初廉頗恃功自傲，不服相如「徒以口舌為勞」而位居其上，揚言「必辱之」（1分）；得知相如以國家為重後，「肉袒負荊」登門謝罪（1分），表現他知錯能改、坦率磊落的性格（1分）。', null, 3),
  ('chushi-q1', 'chushi', 1, 'mc', '「此誠危急存亡之秋也」中，「秋」字的意思是：', '["秋天","收成","時候","一年"]'::jsonb, 'C', '「秋」指關鍵的時刻、時候。', 1),
  ('chushi-q2', 'chushi', 2, 'mc', '下列哪一項不是諸葛亮向後主提出的建議？', '["開張聖聽","賞罰分明，宮中府中不宜異同","親賢臣，遠小人","親自率軍北伐"]'::jsonb, 'D', '北伐由諸葛亮率領；他建議後主廣開言路、賞罰分明、親賢遠佞。', 1),
  ('chushi-q3', 'chushi', 3, 'mc', '「先帝不以臣卑鄙」中「卑鄙」的意思是：', '["品格低下","地位低微，見識淺陋","卑躬屈膝","鄙視別人"]'::jsonb, 'B', '古今異義：古義指出身低微、見識淺陋，今義指品格惡劣。', 1),
  ('chushi-q4', 'chushi', 4, 'short', '全文多次提及「先帝」，試分析作者這樣寫的用意。', null, '①借先帝的權威勸勉後主，使建議更易被接納，例如「以光先帝遺德」（1分）；②提醒後主繼承先帝遺志，興復漢室（1分）；③追述先帝知遇之恩，表明自己北伐是為了「報先帝而忠陛下」（1分）；④使全文語氣委婉懇切，情理兼備（1分）。', null, 4),
  ('chushi-q5', 'chushi', 5, 'short', '「親賢臣，遠小人，此先漢所以興隆也；親小人，遠賢臣，此後漢所以傾頹也。」運用了甚麼寫作手法？有何作用？', null, '對比（亦可答對偶、正反論證）（1分）。以先漢興隆與後漢傾頹作正反對照（1分），突出用人得失關乎國家興亡，有力地勸勉後主親賢遠佞（1分）。', null, 3),
  ('shishuo-q1', 'shishuo', 1, 'mc', '作者認為擇師的標準是：', '["年紀比自己大","地位比自己高","道之所存，師之所存","學問比自己淵博的聖人"]'::jsonb, 'C', '「無貴無賤，無長無少，道之所存，師之所存也。」', 1),
  ('shishuo-q2', 'shishuo', 2, 'mc', '「小學而大遺」批評的是哪一種行為？', '["只學習句讀而不解決疑惑","小時候不讀書","只學小學課程","大學生忘記小學知識"]'::jsonb, 'A', '學了句讀這些小事，卻放棄了解惑這件大事。', 1),
  ('shishuo-q3', 'shishuo', 3, 'mc', '第三段引孔子「三人行，則必有我師」，屬於哪種論證方法？', '["比喻論證","引用論證","對比論證","歸謬論證"]'::jsonb, 'B', '引用聖人之言作論據，屬引用論證。', 1),
  ('shishuo-q4', 'shishuo', 4, 'short', '第二段作者運用了三組對比，批評當時恥於從師的風氣。試列出這三組對比，並說明各自帶出的結論。', null, '①古之聖人從師而問，今之眾人恥學於師→聖益聖，愚益愚（2分）；②為兒子擇師，自己卻恥於從師→惑矣／小學而大遺（2分）；③巫醫樂師百工之人不恥相師，士大夫之族群聚而笑之→其智乃反不能及（2分）。', '每組：對比雙方1分，結論1分。', 6),
  ('shishuo-q5', 'shishuo', 5, 'short', '作者寫〈師說〉贈給李蟠的原因是甚麼？', null, '李蟠好古文，通習六藝經傳，不受恥於從師的時俗所限而向作者求學（1分）；作者嘉許他能實行古人從師之道（1分）。', null, 2),
  ('xishan-q1', 'xishan', 1, 'mc', '「自余為僇人，居是州，恆惴慄」反映作者當時的心情是：', '["悠閒自在","經常憂懼不安","興奮期待","憤怒不平"]'::jsonb, 'B', '「惴慄」即恐懼不安；「恆」即經常。', 1),
  ('xishan-q2', 'xishan', 2, 'mc', '「然後知是山之特立，不與培塿為類」寄寓了作者怎樣的情懷？', '["喜愛登山運動","孤高自傲，不與世俗小人同流","渴望回到京城","希望隱居田園"]'::jsonb, 'B', '托物言志：以西山特立比喻自己的高潔品格。', 1),
  ('xishan-q3', 'xishan', 3, 'mc', '題目中「始得」二字最貼切的解釋是：', '["開始建造","第一次真正發現、領略","開始得到官職","剛剛到達永州"]'::jsonb, 'B', '結尾「然後知吾嚮之未始遊，遊於是乎始」呼應題目。', 1),
  ('xishan-q4', 'xishan', 4, 'short', '比較第一段與第二段作者遊覽時的心境有何不同。', null, '第一段：作者被貶後「恆惴慄」，漫無目的地遊覽，借醉和夢排遣愁苦，心境苦悶（2分）。第二段：登上西山後「心凝形釋，與萬化冥合」，物我兩忘，得到精神上的解脫（2分）。', null, 4),
  ('xishan-q5', 'xishan', 5, 'short', '作者如何襯托西山之高？試舉兩例。', null, '①「凡數州之土壤，皆在衽席之下」，以俯瞰數州襯托山高（1.5分）；②其他山丘「若垤若穴」、「尺寸千里」，以群山渺小襯托西山高聳（1.5分）；亦可答「縈青繚白，外與天際，四望如一」或「不與培塿為類」。', null, 3),
  ('yueyang-q1', 'yueyang', 1, 'mc', '「覽物之情，得無異乎？」在文中的作用是：', '["總結全文","引出下文遷客騷人因景而悲喜的描寫","描寫洞庭湖景色","讚美滕子京的政績"]'::jsonb, 'B', '以設問帶出第三、四段的「悲」與「喜」。', 1),
  ('yueyang-q2', 'yueyang', 2, 'mc', '「不以物喜，不以己悲」的意思是：', '["不因外物好壞和個人得失而喜悲","不喜歡物質，也不為自己悲傷","不買東西就不會開心","對一切都沒有感情"]'::jsonb, 'A', '古仁人不因外在環境或個人際遇而改變心情。', 1),
  ('yueyang-q3', 'yueyang', 3, 'mc', '「微斯人，吾誰與歸」中「微」的意思是：', '["微小","稍微","如果沒有","隱蔽"]'::jsonb, 'C', '「微」解作「如果沒有」；全句意思是如果沒有這樣的人，我同誰一道呢？', 1),
  ('yueyang-q4', 'yueyang', 4, 'short', '第三、四段分別描寫了怎樣的景色和心情？兩段有何共通之處？', null, '第三段：陰雨連綿、濁浪排空的蕭條景象，遷客騷人「感極而悲」（1分）。第四段：春和景明、皓月千里的明媚景象，遷客騷人「其喜洋洋」（1分）。共通之處：兩者的心情都隨景物變化而改變，即「以物喜，以己悲」（2分），為下文古仁人「不以物喜，不以己悲」作對比。', null, 4),
  ('yueyang-q5', 'yueyang', 5, 'short', '作者寫作本文，除了記樓之外，還有甚麼用意？', null, '①抒發自己「先天下之憂而憂，後天下之樂而樂」的政治抱負（1分）；②以古仁人「不以物喜，不以己悲」勉勵同樣被貶的滕子京（1分）；③亦藉此自勉，不因貶謫而消沉（1分）。', null, 3),
  ('liuguo-q1', 'liuguo', 1, 'mc', '作者認為六國破滅的根本原因是：', '["兵器不鋒利","不善於作戰","賄賂秦國","國君昏庸"]'::jsonb, 'C', '「六國破滅，非兵不利，戰不善，弊在賂秦。」', 1),
  ('liuguo-q2', 'liuguo', 2, 'mc', '「以地事秦，猶抱薪救火」運用了哪些論證方法？', '["引用論證和比喻論證","舉例論證和對比論證","因果論證和歸謬論證","假設論證和舉例論證"]'::jsonb, 'A', '引古人語（引用），以抱薪救火作喻（比喻）。', 1),
  ('liuguo-q3', 'liuguo', 3, 'mc', '文中指齊國雖未賂秦，最終仍滅亡，原因是：', '["齊國兵力太弱","齊國依附秦國而不幫助五國","齊國國君被刺殺","齊國良將被讒言所害"]'::jsonb, 'B', '「與嬴而不助五國也。五國既喪，齊亦不免矣。」', 1),
  ('liuguo-q4', 'liuguo', 4, 'short', '本文的中心論點和兩個分論點分別是甚麼？', null, '中心論點：六國破滅，弊在賂秦（2分）。分論點一：賂秦者因賂秦而力虧，以致破滅（1分）；分論點二：不賂者因失去強援（賂秦者）而不能獨完（1分）。', null, 4),
  ('liuguo-q5', 'liuguo', 5, 'short', '文末「苟以天下之大，而從六國破亡之故事，是又在六國下矣」有何深意？', null, '借古諷今（1分）：北宋疆域遠大於六國，卻向遼和西夏納幣求和，重蹈六國賂秦的覆轍（1分）；作者警告朝廷若不改變，比六國更不如，勸其奮發抗敵（1分）。', null, 3),
  ('shi3-q1', 'shi3', 1, 'mc', '「竹喧歸浣女，蓮動下漁舟」運用了哪種寫作手法？', '["借古諷今","先聞其聲、先見其動，後見其人","對比","誇張"]'::jsonb, 'B', '先寫竹林喧鬧、蓮葉晃動，再點出浣女歸來、漁舟順流而下。', 1),
  ('shi3-q2', 'shi3', 2, 'mc', '〈月下獨酌〉中「對影成三人」的「三人」是指：', '["詩人與兩位朋友","詩人、明月和身影","詩人、花和酒","詩人、天和地"]'::jsonb, 'B', '「舉杯邀明月，對影成三人」——詩人、月、影。', 1),
  ('shi3-q3', 'shi3', 3, 'mc', '下列哪一項正確配對了詩歌和體裁？', '["〈山居秋暝〉——七言律詩","〈月下獨酌〉——五言古詩","〈登樓〉——五言律詩","〈月下獨酌〉——七言絕句"]'::jsonb, 'B', '〈山居秋暝〉為五律，〈月下獨酌〉為五古，〈登樓〉為七律。', 1),
  ('shi3-q4', 'shi3', 4, 'short', '〈登樓〉首句「花近高樓傷客心」以美景寫哀情，試加以說明，並指出詩人「傷心」的原因。', null, '春花盛開近樓本是美景，詩人卻感到傷心，以樂景反襯哀情，倍增其哀（2分）。原因是「萬方多難」——國家內憂外患（吐蕃入侵、宦官弄權），詩人憂國傷時（2分）。', null, 4),
  ('shi3-q5', 'shi3', 5, 'short', '〈月下獨酌〉表面熱鬧，實則孤獨。試引詩句說明。', null, '表面熱鬧：「舉杯邀明月，對影成三人」「我歌月徘徊，我舞影零亂」，彷彿有人相伴歌舞（2分）。實則孤獨：開首「獨酌無相親」已點明無人作伴；「月既不解飲，影徒隨我身」可見月和影並非真正的知己，熱鬧只是詩人的想像，更見其孤寂（2分）。', null, 4),
  ('ci3-q1', 'ci3', 1, 'mc', '〈念奴嬌・赤壁懷古〉中，作者主要懷念哪一位歷史人物？', '["曹操","劉備","周瑜","諸葛亮"]'::jsonb, 'C', '「遙想公瑾當年」——公瑾即周瑜。', 1),
  ('ci3-q2', 'ci3', 2, 'mc', '〈聲聲慢〉開首「尋尋覓覓，冷冷清清，淒淒慘慘戚戚」的作用不包括：', '["營造低沉的音韻","由動作、環境到心情層層深入","奠定全詞愁苦的基調","描寫熱鬧的節日氣氛"]'::jsonb, 'D', '十四個疊字寫孤寂愁苦，與熱鬧無關。', 1),
  ('ci3-q3', 'ci3', 3, 'mc', '〈青玉案・元夕〉「那人卻在，燈火闌珊處」中，「那人」象徵：', '["作者的妻子","不慕繁華、孤高自守的人格","元宵節的遊客","賣花燈的小販"]'::jsonb, 'B', '一般認為「那人」寄寓作者不隨波逐流、甘於寂寞的人格。', 1),
  ('ci3-q4', 'ci3', 4, 'short', '〈念奴嬌〉下片如何運用對比手法？表達了作者怎樣的感慨？', null, '以周瑜年少得志、「雄姿英發」、「談笑間、檣櫓灰飛煙滅」，對比作者自己「早生華髮」、功業未成（2分）；表達作者年華老去、壯志難酬的感慨，最後以「人生如夢」自我開解，流露曠達之情（2分）。', null, 4),
  ('ci3-q5', 'ci3', 5, 'short', '〈青玉案・元夕〉上片極寫元宵的熱鬧，與下片有何關係？', null, '上片寫花燈如樹、煙花如雨、寶馬雕車、簫聲魚龍舞，極盡繁華熱鬧（1分）；下片寫「那人」獨在「燈火闌珊處」（1分）；以熱鬧反襯冷清（1分），突出「那人」不與眾人同樂、孤高自守的形象（1分）。', null, 4)
insert into public.writing_questions (id, year, paper, part, question_no, type, genre, prompt, has_material, has_image, source_url, verification) values
  ('2026-1', 2026, '2026', '甲部', 1, '實用寫作', '評論文章', '香城中學小賣部計劃於2026年9月起，全面使用電子支付，同學對此有不同意見。試以香城中學中五甲班學生余君宜的名義，於《香城中學校園報》發表評論文章一篇。文章須自擬標題，並提出對學校小賣部全面使用電子支付的看法。（全文不得多於550字，標點符號計算在內。）', true, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2026 教師會議簡報（卷二甲）'),
  ('2026-2', 2026, '2026', '乙部', 2, '命題寫作', '記敘抒情', '餐膳常伴有甜點，如蛋糕、芝麻糊、冰淇淋等。有時候，食物除了飽腹之外，還有其他意義。試以「眼前的甜點令這頓飯別具意義」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '未能以官方試卷核實；與 HK01、AfterSchool 報道一致。題號按 2024 年起格式（甲部為第1題）推定'),
  ('2026-3', 2026, '2026', '乙部', 3, '命題寫作', '記敘抒情／描寫', '即使在城市中，大自然仍能展現其生命力。如渡輪碼頭旁自由暢泳的魚兒，行人路上生氣勃勃的野草，樓宇間振翅高飛的雀鳥，皆展現著活力和希望。試以「在城市中，我看到了大自然的生命光芒」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '未能以官方試卷核實；HK01、AfterSchool 作「看到」，文匯報、經濟日報作「看見」'),
  ('2026-4', 2026, '2026', '乙部', 4, '命題寫作', '議論', '言語的影響很大，正如古人說：「與人善言，暖於布帛；傷人以言，深於矛戟」，大意是對人說美善的話，比給他衣服更讓人感到溫暖；以惡劣的言語傷害他人，比用利器攻擊他人的傷害更大。試根據以上古語，以「談說話」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '未能以官方試卷核實；與 HK01、AfterSchool 報道大致一致（標點略有出入）'),
  ('2025-1', 2025, '2025', '甲部', 1, '實用寫作', '演講辭', '香城中學將於本學年參與南區義工服務團的「『寵』愛有家」計劃，試以香城中學義工服務團學生代表常天倫的名義，撰寫演講辭一篇，於學校早會時段說明「『寵』愛有家」計劃的意義，並呼籲同學積極支持計劃。（全文不得多於550字，標點符號計算在內。）', true, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2025 教師會議簡報（卷二甲）'),
  ('2025-2', 2025, '2025', '乙部', 2, '命題寫作', '開放（記敘抒情／論說）', '試以「藏在泥土中的寶物」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2025 年卷二試題答題簿'),
  ('2025-3', 2025, '2025', '乙部', 3, '命題寫作', '開放（記敘抒情／論說）', '在白布鞋的污跡上繪畫花朵，活化破舊建築物為時尚藝術館，在緊湊的旅程遇上暴雨可享受片刻悠閒。世事無完美，能為事物或心境增加新的色彩，則事事皆美。試以「為不完美添色彩」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2025 年卷二試題答題簿（來源清單作「建築」「旅程上」「暴風雨」「增添」，已更正）'),
  ('2025-4', 2025, '2025', '乙部', 4, '命題寫作', '議論', '有容：「行事要量力而為，勉強沒有好結果。」修端：「要踏出舒適圈，才可以突破能力的界限。」試寫作文章一篇，談談你對以上兩個觀點的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2025 年卷二試題答題簿（來源清單作「否則沒有好結果」「以上觀點」，已更正）'),
  ('2024-1', 2024, '2024', '甲部', 1, '實用寫作', '書信', '香城中學將於本學年推行「潔淨環境 花香四溢」美化校園計劃，同學在意見收集群組裏各自表達了不同意見。試以香城中學美化校園小組學生代表何英秀的名義，在《校園通訊》刊登一封書信，說明該計劃如何有助學生成長，並鼓勵同學支持計劃。（全文不得多於550字）', true, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2024 教師會議簡報（卷二）'),
  ('2024-2', 2024, '2024', '乙部', 2, '命題寫作', '記敘抒情', '試以「我最想尋回的一件玩具」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2024 教師會議簡報（第二題）'),
  ('2024-3', 2024, '2024', '乙部', 3, '命題寫作', '開放（記敘抒情／論說）', '人生總有大大小小的選擇，無論選擇的結果如何，只要選擇時問心無愧，便已足夠。試以「無愧的選擇」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2024 教師會議簡報（第三題）'),
  ('2024-4', 2024, '2024', '乙部', 4, '命題寫作', '議論', '向華：「遵守諾言是具誠信的表現。」幼羚：「我卻認為，有時候，放棄諾言也是負責任的行為。」試寫作文章一篇，談談你對以上兩個觀點的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2024 教師會議簡報'),
  ('2023-1', 2023, '2023', null, 1, '命題寫作', '記敘抒情', '試以「一次令我百感交集的聚餐」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2023 教師會議簡報'),
  ('2023-2', 2023, '2023', null, 2, '命題寫作', '開放（聯想／思考）', '「偶然，我抬頭一看，發現嫩葉長出來了。原來我們忽略了不少日常生活中的美好。」以上描述中「原來我們忽略了不少日常生活中的美好」，引發了你怎樣的聯想或思考？試結合生活，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2023 教師會議簡報'),
  ('2023-3', 2023, '2023', null, 3, '命題寫作', '議論', '模仿在生活中處處可見。當紅的偶像、著名的藝術品、成功的策略……，均可為模仿對象。有人認為：「模仿缺乏個性。」你同意嗎？試撰文一篇，論述你的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2023 教師會議簡報'),
  ('2022-1', 2022, '2022', null, 1, '命題寫作', '記敘抒情（續寫）', '「我是一套校服，今天要和主人分離，回想過去我們一起生活，別有一番體會。」以上是文章的開首，試以「校服的自述」為題，續寫這篇文章。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2022 教師會議簡報（來源清單作「今日」，已更正）'),
  ('2022-2', 2022, '2022', null, 2, '命題寫作', '開放（看圖）', '試就下圖對你的啟發，以「得不償失」為題，寫作一篇文章。', false, true, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2022 教師會議簡報（來源清單作「寫一篇文章」，已更正）；原題附圖，本站未收錄'),
  ('2022-3', 2022, '2022', null, 3, '命題寫作', '議論', '爺爺：「我當鐘錶匠超過五十年，畢生專注於這門手藝，能做到毫秒不差。」允行：「我是品味生活的咖啡師，也是書寫人生的作家，更是培育後進的武術教練。」各人對人生有不同的追求。有人認為：「與其一生專精一事，不如發展多元人生。」你同意嗎？試撰文一篇，論述你的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2022 教師會議簡報（來源清單作「50年」「分毫不差」等，已更正）'),
  ('2021-1', 2021, '2021', null, 1, '命題寫作', '記敘抒情', '「經過這件事，我才明白到一心是我的知己，是真正了解我的人」，試撰文一篇，記述事件經過，並抒發體會。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '未能以官方原卷核實；據 dselib 試題文字版及港語學整理（來源清單作「時間經過」，已更正）。AfterSchool 版本前有「以下是你在社交網站的帖文：」一句，有待核實'),
  ('2021-2', 2021, '2021', null, 2, '命題寫作', '開放（個人思考）', '在生活中，人們有時會隱藏自己的秘密、情感、想法等等。試以「隱藏」為題，就個人思考或體會，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '未能以官方原卷核實；據港語學整理（來源清單作「寫作文一篇」，已更正）'),
  ('2021-3', 2021, '2021', null, 3, '命題寫作', '議論', '有人認為：「富足的物質條件有利孩子成長。」你同意嗎？試撰文一篇，論述你的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '未能以官方原卷核實；三個來源一致'),
  ('2020-1', 2020, '2020', null, 1, '命題寫作', '記敘描寫（人物）', '在我認識的人當中，他最能體現「嚴以律己，寬以待人」的美德。試寫作文章一篇，描述這位人物的言行。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2020 教師會議簡報'),
  ('2020-2', 2020, '2020', null, 2, '命題寫作', '開放', '在人生路上，面對各種處境，我們都能微笑以對嗎？試以「微笑以對」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2020 教師會議簡報（來源清單作「以微笑以對嗎」，已更正）'),
  ('2020-3', 2020, '2020', null, 3, '命題寫作', '議論', '農曆新年，一心收到親戚送來的禮物。一心說：「每年都送來不合用的東西，不送也罷。」一心的姐姐說：「禮多人不怪。」一心的弟弟說：「千里送鵝毛，禮輕情意重。」各人對送禮都有自己的看法。試以「送禮之我見」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2020 教師會議簡報'),
  ('2019-1', 2019, '2019', null, 1, '命題寫作', '記敘抒情（續寫）', '試以「這一句話，我會記上一輩子。」為首句，續寫這篇文章。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2019 教師會議簡報'),
  ('2019-2', 2019, '2019', null, 2, '命題寫作', '開放（體會／聯想）', '以下段落節錄自詩歌《想想別人》：
