  ('2019-3', 2019, '2019', null, 3, '命題寫作', '議論', '俗語說「萬般皆下品，惟有讀書高」，也有人說「讀書無用」。試寫作文章一篇，談談你對「讀書無用」的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2019 教師會議簡報（來源清單作「唯有」，已更正）'),
  ('2018-1', 2018, '2018', null, 1, '命題寫作', '記敘描寫抒情', '舊地重遊，看到眼前景象，難免興起一番感受。試以「重遊舊地所見有感」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2018 教師會議簡報'),
  ('2018-2', 2018, '2018', null, 2, '命題寫作', '開放（想像／思考）', '在日常生活之中，有各種各樣的禁區。試就個人的想像或思考，以「禁區」為題，寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：HKEAA 2018 教師會議簡報'),
  ('2018-3', 2018, '2018', null, 3, '命題寫作', '議論', '試以「談知己」或「談敵人」為題，寫作文章一篇。（請把文題寫在答題簿的第一行。）', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '題目主體已以 HKEAA 2018 教師會議簡報核實；括號內提示只見於來源清單，未核實'),
  ('2017-1', 2017, '2017', null, 1, '命題寫作', '記敘抒情（指定末句）', '試撰寫文章一篇，並以「自此之後，我終於解開了心結。」為末句收結全文。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2017 年卷二試卷掃描（OCR）'),
  ('2017-2', 2017, '2017', null, 2, '命題寫作', '開放（聯想／思考）', '「足印」雖是平常事物，卻可以引起聯想，或牽動思緒，又或啟發思考。試以「足印」為題，就個人體會寫作文章一篇。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2017 年卷二試卷掃描（OCR）'),
  ('2017-3', 2017, '2017', null, 3, '命題寫作', '議論', '有人說憤怒是壞事，有人說憤怒是好事，有人說處理憤怒的情緒需要智慧……試以「談憤怒」為題寫作文章一篇，談談你對憤怒的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2017 年卷二試卷掃描（OCR）'),
  ('2016-1', 2016, '2016', null, 1, '命題寫作', '記敘抒情（指定首句）', '試以「熱鬧過後，我卻感到失落。」為首句，續寫這篇文章。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2016 年卷二試卷掃描（OCR）'),
  ('2016-2', 2016, '2016', null, 2, '命題寫作', '開放（補題）', '有人在活動當中找到快樂，有人在大自然之中找到快樂，有人在某個時刻、場景之中找到快樂……，你在什麼之中找到快樂呢？試為「我在＿＿＿＿之中找到快樂」補上一詞，並以此為題，寫作文章一篇。請把文題寫在答題簿的第一行。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2016 年卷二試卷掃描（OCR）'),
  ('2016-3', 2016, '2016', null, 3, '命題寫作', '議論', '有人認為「傳統往往是創新的包袱」。試談談你對這句話的看法。', false, false, 'https://learnsmart.edu.hk/blog/dse-%E4%B8%AD%E6%96%87%E4%BD%9C%E6%96%87%E9%A1%8C%E7%9B%AE', '官方：2016 年卷二試卷掃描（OCR）'),
  ('2015-1', 2015, '2015', null, 1, '命題寫作', '記敘抒情（日記續寫）', '以下是你日記的第一段：
